class Client:
    def __init__(self):
        self.items = {}
        self.calls = []

    def _reply(self, item, public=False):
        result = deepcopy(item)
        for field in result['spec']['fields']:
            value = field.pop('value', None)
            state = {'has_value': bool(value)}
            if public and field['sensitive'] is False and value:
                state['value'] = value
            result['state']['fields'][field['name']] = state
        return result

    def create_credential(self, vault, key, fields, *, description=None):
        self.calls.append(('create', vault, key))
        assert (vault, key) not in self.items
        self.items[vault, key] = {'id': vault + '-' + key, 'key': key, 'type': 'credential',
            'version': 1, 'spec': {'provider': 'kernel', 'fields': deepcopy(fields)},
            'state': {'provider': 'kernel', 'status': 'ready' if all(
                not field['required'] or field.get('value') for field in fields) else 'pending_collection',
                'fields': {}}, 'available_operations': [{'type': 'collect'}, {'type': 'fill'}]}
        return self._reply(self.items[vault, key])

    def get_credential(self, vault, key, *, include_public_values=False):
        self.calls.append(('get', vault, key, include_public_values))
        item = self.items.get((vault, key))
        return self._reply(item, include_public_values) if item else None

    def update_credential(self, vault, key, *, version, fields, expected_item_id):
        self.calls.append(('update', vault, key, version))
        item = self.items[vault, key]
        assert version == item['version'] and expected_item_id == item['id']
        for definition in item['spec']['fields']:
            definition.pop('value', None)
            value = fields[definition['name']]['value']
            if value is not None:
                definition['value'] = value
        item['version'] += 1
        item['state']['status'] = 'ready' if all(not field['required'] or field.get('value')
            for field in item['spec']['fields']) else 'pending_collection'
        return self._reply(item)

    def collect(self, vault, key):
        self.calls.append(('collect', vault, key))
        item = self._reply(self.items[vault, key])
        item['action'] = {'name': 'collect', 'url': 'https://vault.kernel.sh/collect/synthetic-capability',
                          'expires_at': '2026-10-09T00:00:00Z'}
        return item


